('forecast:dublin-datacentre-connections', 'sample', 'forecast:dublin-datacentre-connections', 'Will the Irish grid operator offer new connections to large data centres in the Dublin region within twelve months?', 'Dublin grid accepts new data centres within a year?', 'energy', '2027-10-07T22:14:05+00:00'::timestamptz, 'Resolves YES if the grid operator publishes connection offers, or a new policy, letting data centres of 10 MW or more connect in the Dublin region before the end date.', null),
('forecast:russia-smaller-grain-quota', 'sample', 'forecast:russia-smaller-grain-quota', 'Will Russia''s next seasonal grain export quota be set below the previous season''s quota?', 'Will Russia set a smaller grain export quota than last season?', 'trade', '2026-12-16T22:14:05+00:00'::timestamptz, 'Resolves YES if the government decree setting the next seasonal grain export quota gives a total below the previous season''s total and is published before the end date.', null),
('forecast:arabica-record-high-three-months', 'sample', 'forecast:arabica-record-high-three-months', 'Will front-month arabica coffee futures in New York settle at a record high within three months?', 'Will arabica futures hit a record high within three months?', 'commodities', '2027-01-05T22:14:05+00:00'::timestamptz, 'Resolves YES if the front-month New York arabica futures contract settles above its all-time highest settlement on any trading day before the end date.', null),
('forecast:china-lpr-cut-next-fixing', 'sample', 'forecast:china-lpr-cut-next-fixing', 'Will China''s one-year loan prime rate be set lower at the next monthly fixing?', 'Will China cut its one-year loan prime rate next month?', 'finance', '2026-10-23T22:14:05+00:00'::timestamptz, 'Resolves YES if the one-year loan prime rate published at the next monthly fixing is lower than the current rate.', null),
('forecast:iron-ore-higher-in-three-months', 'sample', 'forecast:iron-ore-higher-in-three-months', 'Will the benchmark seaborne iron ore price be higher three months after this question opened than on its opening date?', 'Will iron ore prices be higher in three months?', 'commodities', '2026-12-08T22:14:05+00:00'::timestamptz, 'Resolves YES if the benchmark seaborne iron ore price on the end date is above its level on the opening date.', null),
('forecast:egypt-imf-review-on-time', 'sample', 'forecast:egypt-imf-review-on-time', 'Will the IMF Executive Board complete the next review of Egypt''s lending programme by its scheduled date?', 'Will the IMF board approve Egypt''s next review on schedule?', 'economy', '2026-12-21T22:14:05+00:00'::timestamptz, 'Resolves YES if the IMF announces that its Executive Board has completed the review on or before the end date.', null),
('forecast:eu-cbam-next-phase-eased', 'sample', 'forecast:eu-cbam-next-phase-eased', 'Will the European Commission formally propose delaying or simplifying the next phase of the Carbon Border Adjustment Mechanism within four months?', 'Will the EU delay or simplify the next CBAM phase?', 'policy', '2027-02-04T22:14:05+00:00'::timestamptz, 'Resolves YES if the European Commission publishes a legislative proposal or implementing act that postpones or simplifies obligations in the next CBAM phase before the end date.', null),
